package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for KeyedObjects2D.removeObject.
 */
public class KeyedObjects2D_removeObject_TriageGen0Test {

    private KeyedObjects2D dataset;

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }

    @Test
    public void testRemoveObject_ClearsSingleObjectAndRemovesRow() {
        // Setup: Add one object
        String rKey = "Row1";
        String cKey = "Col1";
        dataset.addObject("Value1", rKey, cKey);

        // Verify initial state
        assertEquals(1, dataset.getRowCount());
        assertEquals("Value1", dataset.getObject(rKey, cKey));

        // Action: Remove the only object
        dataset.removeObject(rKey, cKey);

        // Verify: Row should be removed because it's empty
        assertEquals(0, dataset.getRowCount());
        assertNull(dataset.getObject(rKey, cKey));
    }

    @Test
    public void testRemoveObject_ClearsObjectButKeepsRowNotEmpty() {
        // Setup: Two objects in the same row
        String rKey = "Row1";
        String cKey1 = "Col1";
        String cKey2 = "Col2";
        dataset.addObject("Val1", rKey, cKey1);
        dataset.addObject("Val2", rKey, cKey2);

        // Action: Remove one object
        dataset.removeObject(rKey, cKey1);

        // Verify: Row should still exist because Col2 is not null
        assertEquals(1, dataset.getRowCount());
        assertNull(dataset.getObject(rKey, cKey1));
        assertEquals("Val2", dataset.getObject(rKey, cKey2));
    }

    @Test
    public void testRemoveObject_ClearsColumnEntirely() {
        // Setup: Two rows, one object in Col1, one object in Col2
        // We want to clear Col1 completely
        String r1 = "R1";
        String r2 = "R2";
        String c1 = "C1";
        String c2 = "C2";

        dataset.addObject("V1", r1, c1);
        dataset.addObject("V2", r2, c2);

        // Action: Remove C1 from R1. 
        // Since R1 will become empty, R1 is removed.
        // Then the logic checks if the column (C1) is empty across all rows.
        dataset.removeObject(r1, c1);

        // Verify: R1 is gone. C1 is now empty in all remaining rows (R2 doesn't have C1).
        // The column removal logic triggers if allNull is true.
        assertEquals(1, dataset.getRowCount());
        assertNull(dataset.getObject(r1, c1));
        assertEquals("V2", dataset.getObject(r2, c2));
    }

    @Test
    public void testRemoveObject_ColumnRemovalTriggered() {
        // Setup: Two rows, both have an object in C1.
        // If we remove R1's C1, R1 is deleted. 
        // Then we check if C1 is empty across all rows.
        String r1 = "R1";
        String r2 = "R2";
        String c1 = "C1";
        String c2 = "C2";

        dataset.addObject("V1", r1, c1);
        dataset.addObject("V2", r2, c1); // Same column
        dataset.addObject("V3", r2, c2);

        // Action: Remove object at (R1, C1)
        // 1. R1 becomes empty -> R1 is removed from rows/rowKeys.
        // 2. Check column C1: R2 has C1 ("V2") -> allNull = false.
        dataset.removeObject(r1, c1);

        assertEquals(1, dataset.getRowCount());
        assertEquals("V2", dataset.getObject(r2, c1));
    }

    @Test
    public void testRemoveObject_WhenColumnBecomesEmptyAcrossAllRows() {
        // Setup: 
        // R1: [C1: "V1", C2: "V2"]
        // R2: [C1: "V3"]
        // We remove R1,C1. R1 is not empty (has C2). 
        // But if we remove R1,C1 and R2,C1, the column C1 should be cleared from all rows.

        String r1 = "R1";
        String r2 = "R2";
        String c1 = "C1";
        String c2 = "C2";

        dataset.addObject("V1", r1, c1);
        dataset.addObject("V2", r1, c2);
        dataset.addObject("V3", r2, c1);

        // Step 1: Remove R2, C1. R2 becomes empty and is removed.
        dataset.removeObject(r2, c1);

        // Now R1 has [C1: "V1", C2: "V2"]. 
        // Column C1 still has "V1" in R1, so allNull for column is false.
        assertEquals(1, dataset.getRowCount());
        assertEquals("V1", dataset.getObject(r1, c1));

        // Step 2: Remove R1, C1.
        // R1 has [C1: null, C2: "V2"]. R1 is NOT empty.
        // Check Column C1: R1 has null, R2 is gone. allNull = true.
        // Column C1 is cleared from all rows (calls removeValue).
        dataset.removeObject(r1, c1);

        assertEquals(1, dataset.getRowCount());
        assertNull(dataset.getObject(r1, c1));
        assertEquals("V2", dataset.getObject(r1, c2));
    }

    @Test
    public void testRemoveObject_EmptyDataset() {
        // Testing edge case: remove from empty dataset
        // This might throw NullPointerException depending on implementation of getRowIndex
        // but based on the code provided, we assume valid keys or handle gracefully.
        try {
            dataset.removeObject("NonExistent", "NonExistent");
        } catch (Exception e) {
            // If the implementation throws, it's a known behavior for this specific code snippet
        }
    }
}
